import {isExpansionV65} from './expansion-profile-v65.js';
const hash=value=>{let n=2166136261;for(const c of value)n=Math.imul(n^c.charCodeAt(0),16777619)>>>0;return n;};
export const dueBlockchainV65=run=>isExpansionV65(run)&&!run.flags.blockchain65_seen&&run.turn>=4&&run.turn<=15&&hash(`${run.seed}:${run.turn}:blockchain`)%100<28;
export const createBlockchainContextV65=returnEventId=>({version:1,stage:0,returnEventId,route:'research'});
const roleCopy=run=>({system:'順哥看著你的系統工程師名片，先問現有機器能不能借來跑節點。',ai:'你原本準備模型，順哥先問能不能順便懂共識機制；你看了一眼資料庫，自增鍵這次也救不了整條鏈。',mis:'節點還沒有，順哥先問機房哪台還有空；你得先把既有備份和新願景分開。',design:'順哥要你先畫出錢包流程，你問使用者到底要解決什麼問題，不能只把按鈕畫成金幣。',sales:'順哥想請你找第一位客戶，你得先問公司究竟能交付什麼，不然名片比產品先上鏈。',bd:'順哥要借你的人脈約夥伴，你得先區分真的合作方和願意喝咖啡的人。',project:'會議已經開始，工期還沒有，你先替不存在的人力留一個不敢填的欄位。',product:'你先問鏈要解決哪個問題，順哥則想先讓這個名詞進下一版產品路線。',finance:'你得把研發、申請和運行成本分開列；「未來很大」暫時不能放進現金欄。',accounting:'別人想把交易記上鏈，你先問這筆支出到底附哪張單。',hr:'順哥問能不能找懂鏈的人，你拿到的預算卻還不像要新增一個人。',admin:'順哥請你找會議室和合作窗口，你先確認這條鏈是不是又要行政接成線。',executive:'順哥把跨部門計畫交到你面前，組織圖畫得出來，人力還在別張表上。'}[run.actualRoleId]||'你先問自己要接哪一段，不替所有問題一起點頭。');
const stages=[
 {speaker:'action',title:'區塊鏈支線開始｜順哥說，這次要連成一條。',body:'順哥在會議室開了一份區塊鏈提案，想找夥伴、備專利資料，再把概念做成可交代的計畫。大家翻到需求頁，才發現那頁還有很多空格。',quote:'先把資源湊起來。報告能說清楚，事情才有得談。',choices:['先拆需求與驗證問題，找一個能做小測試的範圍。','先整理合作窗口與條件，別把合照當成簽約。','請玩具鵝保管第一個區塊；牠至少不會亂改歷史。']},
 {speaker:'action',title:'人脈還沒接上，報告先有截止日。',body:'順哥把聯絡清單、報告與專利文件排成三欄。幾輪找資源、談人脈之後，報告已堆到桌角，這輪甚至把專利申請送了出去；送件沒有替公司變出產品，更不等於已核准。接下來要問的，還是誰出錢、誰真的有空做。',quote:'資料先有來源，合作先有範圍。別替還沒同意的人填名字。',choices:['核對既有技術與資料來源，準備可討論的報告與權利清單。','回嘴：人脈不是免付費工程師，先把資源與誰負責講清楚。','讓玩具鵝當專利審稿員，每個空白都蓋「尚待確認」。']},
 {speaker:'wing',title:'預算有一點，人力請從現有名單挑。',body:'翅膀聽完說：「區塊鏈不是很紅？我們也做。」順哥遞上人力與經費表，換來一筆像開玩笑的少量預算，外加倉庫的舊主機。新聘的人沒有，系統、AI、MIS等現有工程師被點名兼任，原本的交付也沒撤。翅膀把簡報翻回願景那一頁。',quote:'錢先給這一點，硬體用現成的。現有工程師順便做就好了，哪有每次都要加人。',choices:['縮成小範圍驗證，把做不到與不承諾的部分寫清楚。','回嘴：現有人力不是無限複製，沒有預算就別要求整條鏈一起長。','請印表機複印硬體工程師名牌，當場證明紙有人、人沒有。']},
 {speaker:'action',title:'區塊鏈支線結束｜鏈沒有上線，資料先封存。',body:'幾輪聯絡與報告走完，報告寫了、專利申請也送了，夥伴投入與人力卻仍沒有湊到能繼續的程度。順哥收起提案，宣布這輪停止，現有工程師回去接原本的工作。這次沒有靠一頁新名詞跳成新事業。',quote:'先收攤。做過與沒做到的分開記，別把停下來寫成已完成上線。',choices:['封存報告、往來與未確認事項，把工作還回原本範圍。','回嘴：下次先把預算跟人準備好，別再用願景當人力。','替玩具鵝的第一個區塊辦退役典禮，不另外加開檢討會。']}
];
export function getBlockchainEventV65(run){const c=run.blockchainContext;if(!isExpansionV65(run)||!c||c.version!==1||!stages[c.stage])throw new Error('Invalid blockchain scene');const s=stages[c.stage];return {id:`blockchain65-${c.stage}`,kind:'blockchain',speaker:s.speaker,title:s.title,body:s.body+(c.stage===1?' 前一幕你先選擇'+({research:'拆驗證問題',contacts:'核對合作窗口',goose:'讓玩具鵝看住原始版本'}[c.route]||'整理現有資料')+'，這輪就從那一欄往下追。':'')+(c.stage===0?' '+roleCopy(run):''),wing:s.quote,scope:'work',scene:'meeting',era:c.stage===0?'跨部門計畫・開始':c.stage===3?'跨部門計畫・結束':'跨部門計畫・進行中',sourceIds:['characterFiction'],participants:c.stage===2?['action','wing']:['action'],blockchain:{stage:c.stage,total:4},choices:s.choices.map((text,index)=>({text,result:'',delta:{},...(index===2?{wild:true}:{})}))};}
export function resolveBlockchainChoiceV65(run,index,ticket){const ev=getBlockchainEventV65(run),c=run.blockchainContext;if(![0,1,2].includes(index)||!Number.isFinite(ticket)||ticket<0||ticket>=1)throw new Error('Invalid blockchain choice');const stage=c.stage,route=stage===0?['research','contacts','goose'][index]:stage===2?'budget':stage===3?'closed':c.route,target=ev.speaker,affinityDelta=index===1?-5:index===0?3:ticket<.6?1:-2;return {label:stage===3?'這輪區塊鏈計畫已收攤':'這一幕已有回覆',result:stage===0?`你選擇${index===0?'先拆驗證問題':index===1?'先核對夥伴與條件':'先讓玩具鵝保管不亂改的那一頁'}，順哥把下一步寫進清單。沒有替公司當場變出新預算，也還沒有誰同意免費兼任。`:stage===1?'你把資料與資源缺口整理好，順哥收下厚厚的報告，這輪專利申請也正式送出。送件紀錄留了日期，沒有宣稱已經核准；人脈清單上願意聊的人不少，願意投入的人力仍等回覆。':stage===2?index===1?'翅膀把臉拉下來，說你先不要只談困難。你把低預算、兼任名單與現有交付寫在同一張表，沒有替有限的人力承諾無限工作。':index===2?'印表機吐出三張名牌，現場仍只有原來的人。順哥把紙收好，請翅膀確認這輪只能做的小範圍，沒有把印出來的人當成新增編制。':'你把範圍縮到能驗證的一小段，明列仍缺的人力與費用。現有工程師沒有突然變成三個人，原本工作也留在排程上。':'順哥宣布這輪停止，文件和未完成事項各自封存。你回去接原本的工作，沒有多領一份區塊鏈薪水，也沒有把收攤包裝成順利上線。',delta:stage===2?{mood:index===1?-3:1,boss:index===1?-9:index===2?-3:0,skill:index===0?2:0}:{mood:stage===3?3:1,skill:index===0?2:0,trust:index===1?-2:1},outcome:{version:1,stage,target,affinityDelta,route,done:stage===3},route,done:stage===3};}
export function isBlockchainOutcomeV65(run,row){const x=row?.blockchainOutcome;return Boolean(isExpansionV65(run)&&row?.kind==='blockchain'&&[0,1,2].includes(row.choiceIndex)&&x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join(',')==='affinityDelta,done,route,stage,target,version'&&x.version===1&&Number.isInteger(x.stage)&&x.stage>=0&&x.stage<4&&row.eventId===`blockchain65-${x.stage}`&&x.target===(x.stage===2?'wing':'action')&&row.speaker===x.target&&Number.isInteger(x.affinityDelta)&&x.affinityDelta>=-8&&x.affinityDelta<=8&&(x.stage===2?x.route==='budget':x.stage===3?x.route==='closed':['research','contacts','goose'].includes(x.route))&&x.done===(x.stage===3));}
